import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"Индекс Правовых Положений","description":"","frontmatter":{},"headers":[],"relativePath":"ru/92-法律条文索引.md","filePath":"ru/92-法律条文索引.md","lastUpdated":null}'),h={name:"ru/92-法律条文索引.md"};function i(l,t,o,b,n,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="индекс-правовых-положении" tabindex="-1">Индекс Правовых Положений <a class="header-anchor" href="#индекс-правовых-положении" aria-label="Permalink to &quot;Индекс Правовых Положений&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>Номер документа</td><td>92</td></tr><tr><td>Модуль</td><td>Приложения и справочные материалы</td></tr><tr><td>Ключевые слова</td><td>правовой индекс, Симбиотическая Конституция, трудовой закон, закон о защите прав потребителей, сопутствующие законы</td></tr></tbody></table><h2 id="i-пояснения-к-индексу" tabindex="-1">I. Пояснения к индексу <a class="header-anchor" href="#i-пояснения-к-индексу" aria-label="Permalink to &quot;I. Пояснения к индексу&quot;">​</a></h2><p>Настоящий индекс охватывает основные действующие правовые документы Симбиотической Цивилизации Якоря и их ключевые положения, классифицированные по правовой иерархии и отраслям. Сфера индекса охватывает Симбиотическую Конституцию, Симбиотический Трудовой Закон, Закон о Защите Прав Потребителей, а также пять сопутствующих законов об образовании, медицинском обеспечении, жилье, окружающей среде и антимонопольном регулировании. Каждая запись указывает название закона, номер положения и краткое изложение основного содержания положения. Настоящий индекс является справочным инструментом; полные тексты правовых положений и судебные разъяснения см. в официальных текстах соответствующих законов.</p><h2 id="ii-симбиотическая-конституция" tabindex="-1">II. Симбиотическая Конституция <a class="header-anchor" href="#ii-симбиотическая-конституция" aria-label="Permalink to &quot;II. Симбиотическая Конституция&quot;">​</a></h2><p>Симбиотическая Конституция является основным законом Симбиотической Цивилизации Якоря, обладающим высшей юридической силой, принятым в момент официального установления симбиотической цивилизации.</p><table tabindex="0"><thead><tr><th>Номер положения</th><th>Основное содержание</th></tr></thead><tbody><tr><td>Статья 1</td><td>Устанавливает Вселенную Хэнъюань (Изначальную Вселенную Ваньлин Хэнмао) управляемой областью Симбиотической Цивилизации Якоря; основная цель симбиотической цивилизации — достижение симбиоза Десяти Тысяч Рас и возвышения вселенной</td></tr><tr><td>Статья 2</td><td>Устанавливает антихищничество как основополагающую позицию цивилизации, запрещая хищническую культивацию и хищничество ресурсов в любых формах</td></tr><tr><td>Статья 3</td><td>Устанавливает «возвращение права выбора судьбы и эволюции всем живым существам» как основную концепцию цивилизации</td></tr><tr><td>Статья 4</td><td>Устанавливает больше работы — больше прибыли; самостоятельный рост; путь для каждого; и совместное продвижение Десяти Тысяч Рас как основные политики цивилизации</td></tr><tr><td>Статья 5</td><td>Устанавливает систему свободного открытия Трёхсот Изначальных Систем Культивации; никакая организация или индивид не может монополизировать права передачи систем культивации</td></tr><tr><td>Статья 6</td><td>Устанавливает Механизм Подряда, Связанного с Результатом, как основную систему распределения ресурсов</td></tr><tr><td>Статья 7</td><td>Устанавливает Стратегию Активации 20 % как поэтапную национальную цель</td></tr><tr><td>Статья 8</td><td>Устанавливает принцип Реальности как Основы: реальный мир — единственный реальный мир, вымышленные установки не имеют юридической силы</td></tr><tr><td>Статья 9</td><td>Устанавливает Четырёхэтапный Путь Возвышения как долгосрочную стратегию развития цивилизации</td></tr><tr><td>Статья 10</td><td>Устанавливает принцип равенства Десяти Тысяч Рас; все формы жизни равны перед законом</td></tr><tr><td>Статья 11</td><td>Устанавливает принцип симбиотической эволюции; индивидуальная эволюция не должна осуществляться за счёт прав на эволюцию других индивидов или коллективов</td></tr><tr><td>Статья 12</td><td>Устанавливает принцип больше работы — больше прибыли; распределение ресурсов основывается на вкладе как базовом критерии</td></tr><tr><td>Статья 13</td><td>Устанавливает принцип самостоятельного роста; уважается право каждого живого существа на самостоятельный выбор эволюции</td></tr><tr><td>Статья 14</td><td>Устанавливает принцип пути для каждого; государство обязано предоставить каждому живому существу базовый путь эволюции и гарантию ресурсов</td></tr><tr><td>Статья 15</td><td>Устанавливает принцип устойчивости; всё развитие должно учитывать устойчивость изначальной основы вселенной</td></tr><tr><td>Статьи 16–25</td><td>Предусматривают основные права всех живых существ: право выбора эволюции, право получения ресурсов культивации, право на равную защиту, право участия в симбиозе, право сохранения культуры, право на помощь и обжалование, право на личную свободу, право на личное достоинство, право на свободу вероисповедания и право на свободу выражения</td></tr><tr><td>Статьи 26–31</td><td>Предусматривают основные обязанности всех живых существ: обязанность соблюдать закон, поддерживать симбиотический порядок, вносить трудовой вклад, защищать окружающую среду, уважать права других и наставлять начинающих культиваторов</td></tr><tr><td>Статья 32</td><td>Устанавливает Собрание Якоря как высший орган власти, состоящий из представителей Десяти Тысяч Рас в пропорции</td></tr><tr><td>Статья 33</td><td>Устанавливает Симбиотический Исполнительный Комитет как высший административный орган</td></tr><tr><td>Статья 34</td><td>Устанавливает Симбиотический Суд как высший судебный орган, независимо осуществляющий судебную власть</td></tr><tr><td>Статья 35</td><td>Устанавливает Надзорный Комитет Якоря как независимый надзорный орган</td></tr><tr><td>Статья 36</td><td>Предусматривает законодательную процедуру: законопроект принимается большинством более половины Собрания Якоря</td></tr><tr><td>Статья 37</td><td>Предусматривает процедуру внесения поправок в Конституцию: она должна быть принята большинством более двух третей Собрания Якоря и одобрена более чем половиной населения на референдуме</td></tr><tr><td>Статья 38</td><td>Устанавливает систему конституционного контроля; Симбиотический Суд имеет право объявлять законы, противоречащие Конституции, недействительными</td></tr><tr><td>Статья 39</td><td>Устанавливает систему конституционного судопроизводства; все живые существа могут непосредственно возбуждать судебные иски в соответствии с Конституцией</td></tr><tr><td>Статья 40</td><td>Предусматривает систему местного самоуправления; каждая звёздная область и каждая плоскость осуществляют самоуправление в рамках Конституции</td></tr><tr><td>Статья 41</td><td>Устанавливает республиканскую систему Десяти Тысяч Рас; все расы равны в симбиотической цивилизации и осуществляют региональное самоуправление</td></tr><tr><td>Статья 42</td><td>Предусматривает экономическую систему симбиотической цивилизации: на основе подряда, связанного с результатом, с совместным развитием множества форм собственности</td></tr><tr><td>Статья 43</td><td>Предусматривает систему государственной собственности и справедливого распределения ресурсов культивации</td></tr><tr><td>Статья 44</td><td>Устанавливает систему образовательного равенства, гарантирующую каждому живому существу равное право на образование</td></tr><tr><td>Статья 45</td><td>Устанавливает систему всеобщего медицинского обеспечения</td></tr><tr><td>Статья 46</td><td>Устанавливает систему жилищного обеспечения, гарантирующую каждому живому существу базовое право на жильё</td></tr><tr><td>Статья 47</td><td>Предусматривает основные принципы межплоскостного взаимодействия; несанкционированное межплоскостное перемещение запрещено</td></tr><tr><td>Статья 48</td><td>Предусматривает, что законные результаты археологической деятельности ограничиваются абстрактными знаниями и информацией; возврат материи и энергии запрещён</td></tr><tr><td>Статья 49</td><td>Предусматривает основные принципы возврата времени; должен соблюдаться принцип сначала наблюдение, потом ограниченное вмешательство</td></tr><tr><td>Статья 50</td><td>Предусматривает, что право толкования Конституции принадлежит Симбиотическому Суду, а право внесения поправок в Конституцию принадлежит Собранию Якоря</td></tr></tbody></table><h2 id="iii-симбиотическии-трудовои-закон" tabindex="-1">III. Симбиотический Трудовой Закон <a class="header-anchor" href="#iii-симбиотическии-трудовои-закон" aria-label="Permalink to &quot;III. Симбиотический Трудовой Закон&quot;">​</a></h2><p>Симбиотический Трудовой Закон является основным законом, регулирующим трудовые отношения и защищающим права и интересы работников, принятым на законодательной основе статьи 42 Симбиотической Конституции.</p><table tabindex="0"><thead><tr><th>Номер положения</th><th>Основное содержание</th></tr></thead><tbody><tr><td>Статья 1</td><td>Цель законодательства: регулировать трудовые отношения, защищать законные права и интересы работников и строить гармоничные симбиотические трудовые отношения</td></tr><tr><td>Статья 2</td><td>Сфера применения: все трудовые отношения во Вселенной Хэнъюань, включая материальный труд, культивационный труд и творческий труд</td></tr><tr><td>Статья 3</td><td>Устанавливает принцип равного трудоустройства работников; дискриминация при приёме на работу по признаку расы, пола, уровня культивации или происхождения запрещена</td></tr><tr><td>Статья 4</td><td>Устанавливает принцип свободного выбора работы; принудительный труд и рабство запрещены</td></tr><tr><td>Статья 5</td><td>Предусматривает систему трудового договора; при установлении трудовых отношений должен заключаться письменный трудовой договор</td></tr><tr><td>Статья 6</td><td>Предусматривает обязательные условия трудового договора: срок договора, содержание работы, оплата труда, рабочее время, охрана труда и социальное страхование</td></tr><tr><td>Статья 7</td><td>Устанавливает восьмичасовой рабочий день и систему рабочего времени не более сорока четырёх часов в неделю</td></tr><tr><td>Статья 8</td><td>Предусматривает ограничения сверхурочной работы: не более одного часа в день, трёх часов в особых случаях и не более тридцати шести часов в месяц</td></tr><tr><td>Статья 9</td><td>Предусматривает нормы оплаты сверхурочной работы: 1,5-кратная оплата за сверхурочную работу в рабочие дни, 2-кратная — в выходные дни и 3-кратная — в официальные праздники</td></tr><tr><td>Статья 10</td><td>Устанавливает систему гарантии минимальной заработной платы; уровень минимальной заработной платы устанавливается каждой звёздной областью в соответствии с местными условиями</td></tr><tr><td>Статья 11</td><td>Предусматривает систему выплаты заработной платы: заработная плата должна выплачиваться ежемесячно работнику лично в денежной форме, без удержаний или необоснованных задержек</td></tr><tr><td>Статья 12</td><td>Устанавливает принцип распределения больше работы — больше прибыли; реализуется система распределения с распределением по труду как основой и сосуществованием множества методов распределения</td></tr><tr><td>Статья 13</td><td>Предусматривает систему безопасности и гигиены труда; работодатели обязаны предоставлять работникам условия безопасности и гигиены труда, соответствующие стандартам</td></tr><tr><td>Статья 14</td><td>Предусматривает защиту особых групп: особая охрана труда реализуется для несовершеннолетних работников, женщин-работниц, работников с инвалидностью и работников с низким уровнем культивации</td></tr><tr><td>Статья 15</td><td>Устанавливает систему профессионального обучения; работодатели обязаны проводить обучение работников профессиональным навыкам</td></tr><tr><td>Статья 16</td><td>Предусматривает трудовые права культиваторов: культивационный труд в равной степени защищается настоящим Законом, а принадлежность результатов культивации определяется договором</td></tr><tr><td>Статья 17</td><td>Устанавливает систему социального страхования работников: пенсионное страхование, медицинское страхование, страхование по безработице, страхование от несчастных случаев на производстве и страхование по беременности и родам</td></tr><tr><td>Статья 18</td><td>Предусматривает систему льгот для работников: работодатели обязаны предоставлять работникам необходимые льготы</td></tr><tr><td>Статья 19</td><td>Устанавливает систему разрешения трудовых споров: четырёхуровневый механизм переговоров, медиации, арбитража и судопроизводства</td></tr><tr><td>Статья 20</td><td>Предусматривает систему профсоюзов; работники имеют право организовывать и вступать в профсоюзы в соответствии с законом для защиты своих законных прав и интересов</td></tr><tr><td>Статья 21</td><td>Предусматривает систему коллективных договоров; профсоюзы представляют работников при заключении коллективных договоров с работодателями</td></tr><tr><td>Статья 22</td><td>Предусматривает, что внутренние правила работодателя должны обсуждаться собранием работников или всеми работниками</td></tr><tr><td>Статья 23</td><td>Предусматривает условия и процедуру расторжения трудовых договоров</td></tr><tr><td>Статья 24</td><td>Предусматривает систему экономической компенсации; работодатели обязаны выплачивать экономическую компенсацию при законном расторжении трудового договора</td></tr><tr><td>Статья 25</td><td>Предусматривает систему компенсации за незаконное расторжение трудового договора</td></tr><tr><td>Статья 26</td><td>Устанавливает систему управления заёмным трудом, регулируя использование заёмного труда</td></tr><tr><td>Статья 27</td><td>Предусматривает особые правила неполного рабочего дня</td></tr><tr><td>Статья 28</td><td>Предусматривает систему надзора и инспекции; органы труда в соответствии с законом осуществляют надзор и инспекцию соблюдения работодателями трудового законодательства</td></tr><tr><td>Статья 29</td><td>Предусматривает юридическую ответственность: работодатели, нарушающие настоящий Закон, несут административную, гражданскую и уголовную ответственность в соответствии с законом</td></tr><tr><td>Статья 30</td><td>Предусматривает дату вступления в силу и право толкования настоящего Закона</td></tr></tbody></table><h2 id="iv-закон-о-защите-прав-потребителеи" tabindex="-1">IV. Закон о Защите Прав Потребителей <a class="header-anchor" href="#iv-закон-о-защите-прав-потребителеи" aria-label="Permalink to &quot;IV. Закон о Защите Прав Потребителей&quot;">​</a></h2><p>Закон о Защите Прав Потребителей является основным законом, защищающим законные права и интересы потребителей и регулирующим деятельность хозяйствующих субъектов.</p><table tabindex="0"><thead><tr><th>Номер положения</th><th>Основное содержание</th></tr></thead><tbody><tr><td>Статья 1</td><td>Цель законодательства: защищать законные права и интересы потребителей, поддерживать социально-экономический порядок и способствовать здоровому развитию симбиотической рыночной экономики</td></tr><tr><td>Статья 2</td><td>Сфера применения: защита прав и интересов потребителей во Вселенной Хэнъюань при покупке и использовании товаров или получении услуг для нужд повседневной жизни</td></tr><tr><td>Статья 3</td><td>Устанавливает основные принципы сделок между хозяйствующими субъектами и потребителями: добровольность, равенство, справедливость и добросовестность</td></tr><tr><td>Статья 4</td><td>Устанавливает принцип защиты государством законных прав и интересов потребителей; государство принимает меры для обеспечения осуществления потребителями своих прав в соответствии с законом</td></tr><tr><td>Статья 5</td><td>Предусматривает девять основных прав потребителей: право на безопасность, право на информацию, право на свободный выбор, право на справедливую сделку, право на возмещение, право на объединение, право на получение знаний, право на уважение и право на контроль</td></tr><tr><td>Статья 6</td><td>Предусматривает право потребителя на безопасность: потребители имеют право на то, чтобы их личная и имущественная безопасность не нарушалась при покупке и использовании товаров и получении услуг</td></tr><tr><td>Статья 7</td><td>Предусматривает право потребителя на информацию: потребители имеют право знать подлинную информацию о приобретаемых или используемых товарах и получаемых услугах</td></tr><tr><td>Статья 8</td><td>Предусматривает право потребителя на свободный выбор: потребители имеют право свободно выбирать товары или услуги</td></tr><tr><td>Статья 9</td><td>Предусматривает право потребителя на справедливую сделку: потребители имеют право на справедливую сделку и право отказываться от принудительных сделок</td></tr><tr><td>Статья 10</td><td>Предусматривает право потребителя на возмещение: потребители, понёсшие личный или имущественный ущерб вследствие покупки и использования товаров или получения услуг, имеют право на возмещение в соответствии с законом</td></tr><tr><td>Статья 11</td><td>Предусматривает основные обязанности хозяйствующих субъектов: исполнять законные и договорные обязательства, принимать контроль, обеспечивать безопасность, предоставлять достоверную информацию, выдавать документы, гарантировать качество, выполнять три гарантии, воздерживаться от несправедливых сделок и от посягательств на личное достоинство</td></tr><tr><td>Статья 12</td><td>Предусматривает обязанность хозяйствующих субъектов по обеспечению безопасности: хозяйствующие субъекты должны гарантировать, что предоставляемые ими товары или услуги соответствуют требованиям защиты личной и имущественной безопасности</td></tr><tr><td>Статья 13</td><td>Предусматривает обязанность хозяйствующих субъектов по раскрытию информации: хозяйствующие субъекты должны предоставлять потребителям достоверную информацию о товарах или услугах, без ложной или вводящей в заблуждение рекламы</td></tr><tr><td>Статья 14</td><td>Предусматривает особые нормы для культивационных продуктов и услуг: хозяйствующие субъекты методов культивации, культивационных инструментов и энергетических продуктов должны обладать особыми квалификациями, а продукция должна проходить сертификацию безопасности</td></tr><tr><td>Статья 15</td><td>Предусматривает регулирование типовых условий: хозяйствующие субъекты не могут использовать типовые условия для исключения или ограничения прав потребителей, а также для смягчения или освобождения от ответственности хозяйствующего субъекта</td></tr><tr><td>Статья 16</td><td>Предусматривает систему возврата без объяснения причин в течение семи дней: потребители, купившие товары дистанционными способами, такими как сеть, имеют право вернуть товары в течение семи дней с даты получения</td></tr><tr><td>Статья 17</td><td>Предусматривает систему трёх гарантий: если предоставляемые хозяйствующими субъектами товары или услуги не соответствуют требованиям качества, потребители могут потребовать ремонта, замены или возврата в соответствии с государственными нормами</td></tr><tr><td>Статья 18</td><td>Предусматривает систему штрафных санкций: если хозяйствующие субъекты предоставляют товары или услуги с обманом, они должны по требованию потребителей увеличить возмещение понесённых убытков, причём сумма дополнительного возмещения составляет три цены приобретённых товаров или стоимости полученных услуг</td></tr><tr><td>Статья 19</td><td>Предусматривает организации потребителей: ассоциации потребителей и другие потребительские организации являются законно созданными общественными организациями, осуществляющими общественный контроль за товарами и услугами и защищающими законные права и интересы потребителей</td></tr><tr><td>Статья 20</td><td>Предусматривает пути разрешения потребительских споров: переговоры и урегулирование с хозяйствующим субъектом, обращение за медиацией в ассоциацию потребителей, жалоба в соответствующие административные органы, передача в арбитраж и подача иска в суд</td></tr><tr><td>Статья 21</td><td>Предусматривает перераспределение бремени доказывания в спорах: для товаров длительного пользования или услуг, таких как отделка, если потребители обнаруживают недостатки в течение шести месяцев с момента получения, бремя доказывания лежит на хозяйствующем субъекте</td></tr><tr><td>Статья 22</td><td>Предусматривает административную и уголовную ответственность хозяйствующих субъектов</td></tr><tr><td>Статья 23</td><td>Предусматривает дату вступления в силу и право толкования настоящего Закона</td></tr></tbody></table><h2 id="v-пять-сопутствующих-законов" tabindex="-1">V. Пять Сопутствующих Законов <a class="header-anchor" href="#v-пять-сопутствующих-законов" aria-label="Permalink to &quot;V. Пять Сопутствующих Законов&quot;">​</a></h2><h3 id="_5-1-закон-о-гарантии-образования" tabindex="-1">5.1 Закон о Гарантии Образования <a class="header-anchor" href="#_5-1-закон-о-гарантии-образования" aria-label="Permalink to &quot;5.1 Закон о Гарантии Образования&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Номер положения</th><th>Основное содержание</th></tr></thead><tbody><tr><td>Статья 1</td><td>Цель законодательства: гарантировать равное право на образование всех живых существ, построить симбиотическую систему образования и способствовать совместному развитию культур Десяти Тысяч Рас</td></tr><tr><td>Статьи 2–5</td><td>Устанавливают принцип образовательного равенства, принцип бесплатного образования (на этапе базового образования), принцип образовательного многообразия и принцип образовательных инноваций</td></tr><tr><td>Статьи 6–10</td><td>Предусматривают архитектуру системы дошкольного образования, обязательного образования, старшего среднего образования, высшего образования и культивационного образования</td></tr><tr><td>Статьи 11–15</td><td>Предусматривают особые системы культивационного образования: учебные нормы Трёхсот Систем, систему наставничества и систему распределения ресурсов культивации</td></tr><tr><td>Статьи 16–20</td><td>Предусматривают права и обязанности преподавателей, систему квалификации преподавателей и гарантию обеспечения преподавателей</td></tr><tr><td>Статьи 21–25</td><td>Предусматривают гарантию инвестиций в образование, строительство образовательных объектов, информатизацию образования, специальное образование и межрасовое образование</td></tr><tr><td>Статьи 26–30</td><td>Предусматривают систему оценки образования, систему контроля образования, юридическую ответственность и дополнительные положения</td></tr></tbody></table><h3 id="_5-2-закон-о-медицинском-обеспечении" tabindex="-1">5.2 Закон о Медицинском Обеспечении <a class="header-anchor" href="#_5-2-закон-о-медицинском-обеспечении" aria-label="Permalink to &quot;5.2 Закон о Медицинском Обеспечении&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Номер положения</th><th>Основное содержание</th></tr></thead><tbody><tr><td>Статья 1</td><td>Цель законодательства: создать систему всеобщего медицинского обеспечения, гарантировать право на здоровье всех живых существ и повысить общий уровень здоровья Десяти Тысяч Рас</td></tr><tr><td>Статьи 2–5</td><td>Устанавливают принцип всеобщего медицинского страхования, принцип бесплатной базовой медицинской помощи, принцип интеграции китайской и западной медицины и принцип включения культивационной медицины</td></tr><tr><td>Статьи 6–10</td><td>Предусматривают многоуровневую систему медицинского страхования: базовое медицинское страхование, страхование от тяжёлых заболеваний, медицинская помощь и коммерческое медицинское страхование</td></tr><tr><td>Статьи 11–15</td><td>Предусматривают управление медицинскими учреждениями, систему медицинского персонала, качество и безопасность медицинской помощи и особые нормы культивационной медицины</td></tr><tr><td>Статьи 16–20</td><td>Предусматривают управление лекарственными средствами, управление медицинскими изделиями, управление энергетическими медицинскими продуктами и систему основных лекарственных средств</td></tr><tr><td>Статьи 21–25</td><td>Предусматривают систему общественного здравоохранения, профилактику и контроль заболеваний, санитарное просвещение, межрасовую медицину и медицинское обеспечение особых групп</td></tr><tr><td>Статьи 26–30</td><td>Предусматривают разрешение медицинских споров, медицинский контроль, юридическую ответственность и дополнительные положения</td></tr></tbody></table><h3 id="_5-3-закон-о-жилищном-обеспечении" tabindex="-1">5.3 Закон о Жилищном Обеспечении <a class="header-anchor" href="#_5-3-закон-о-жилищном-обеспечении" aria-label="Permalink to &quot;5.3 Закон о Жилищном Обеспечении&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Номер положения</th><th>Основное содержание</th></tr></thead><tbody><tr><td>Статья 1</td><td>Цель законодательства: гарантировать базовое право на жильё всех живых существ, построить многоуровневую систему жилищного обеспечения и добиться жилья для всех</td></tr><tr><td>Статьи 2–5</td><td>Устанавливают принцип гарантии права на жильё, принцип жилищной справедливости, принцип сочетания аренды и покупки и принцип устойчивого жилья</td></tr><tr><td>Статьи 6–10</td><td>Предусматривают систему предложения жилья: общественное арендное жильё, обеспечительное арендное жильё, жильё с общей собственностью и коммерческое жильё</td></tr><tr><td>Статьи 11–15</td><td>Предусматривают систему жилищного фонда, систему жилищных субсидий, политику поддержки первого жилья и особую жилищную политику для культиваторов</td></tr><tr><td>Статьи 16–20</td><td>Предусматривают стандарты жилищного строительства, применение пространственных технологий в жилье, зелёные здания и адаптированное для пожилых и безбарьерное жильё</td></tr><tr><td>Статьи 21–25</td><td>Предусматривают регулирование рынка недвижимости, нормы рынка аренды жилья, управление имущественными услугами и гарантию ремонта жилья</td></tr><tr><td>Статьи 26–30</td><td>Предусматривают контроль жилищного обеспечения, юридическую ответственность и дополнительные положения</td></tr></tbody></table><h3 id="_5-4-закон-об-охране-окружающеи-среды" tabindex="-1">5.4 Закон об Охране Окружающей Среды <a class="header-anchor" href="#_5-4-закон-об-охране-окружающеи-среды" aria-label="Permalink to &quot;5.4 Закон об Охране Окружающей Среды&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Номер положения</th><th>Основное содержание</th></tr></thead><tbody><tr><td>Статья 1</td><td>Цель законодательства: защищать и улучшать окружающую среду, предотвращать и контролировать загрязнение и другие общественные бедствия, гарантировать здоровье населения, способствовать строительству космической экологической цивилизации и обеспечивать устойчивое развитие</td></tr><tr><td>Статьи 2–5</td><td>Устанавливают принцип приоритета защиты, принцип преимущественного предотвращения, принцип комплексного управления, принцип участия общественности и принцип ответственности за ущерб</td></tr><tr><td>Статьи 6–10</td><td>Предусматривают систему экологического контроля и управления, систему экологических стандартов, систему оценки воздействия на окружающую среду, систему экологического мониторинга и межплоскостное экологическое управление</td></tr><tr><td>Статьи 11–15</td><td>Предусматривают предотвращение и контроль загрязнения воздуха, воды, почвы, энергетического загрязнения и загрязнения законов</td></tr><tr><td>Статьи 16–20</td><td>Предусматривают обработку твёрдых отходов, предотвращение и контроль шумового загрязнения, радиоактивного загрязнения, экологическую защиту и защиту биоразнообразия</td></tr><tr><td>Статьи 21–25</td><td>Предусматривают контроль экологического воздействия культивационной деятельности, экологическую защиту добычи энергии и экологические требования межплоскостной археологии</td></tr><tr><td>Статьи 26–30</td><td>Предусматривают раскрытие информации и участие общественности, экологические публичные иски, юридическую ответственность и дополнительные положения</td></tr></tbody></table><h3 id="_5-5-антимонопольныи-закон" tabindex="-1">5.5 Антимонопольный Закон <a class="header-anchor" href="#_5-5-антимонопольныи-закон" aria-label="Permalink to &quot;5.5 Антимонопольный Закон&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Номер положения</th><th>Основное содержание</th></tr></thead><tbody><tr><td>Статья 1</td><td>Цель законодательства: предотвращать и пресекать монополистические действия, защищать добросовестную рыночную конкуренцию, повышать эффективность функционирования экономики, защищать интересы потребителей и общественные интересы общества и способствовать здоровому развитию симбиотической рыночной экономики</td></tr><tr><td>Статьи 2–5</td><td>Устанавливают базовую позицию конкурентной политики, систему проверки добросовестной конкуренции, запрет монополистических соглашений, запрет злоупотребления доминирующим положением на рынке и контроль концентрации хозяйствующих субъектов</td></tr><tr><td>Статьи 6–10</td><td>Предусматривают определение и освобождение монополистических соглашений, горизонтальные монополистические соглашения, вертикальные монополистические соглашения и монополистические действия отраслевых ассоциаций</td></tr><tr><td>Статьи 11–15</td><td>Предусматривают определение доминирующего положения на рынке, типы действий, составляющих злоупотребление доминирующим положением, и запрет хищнического ценообразования</td></tr><tr><td>Статьи 16–20</td><td>Предусматривают стандарты уведомления о концентрации хозяйствующих субъектов, процедуру проверки, дополнительные ограничительные условия и решения о запрете концентрации</td></tr><tr><td>Статьи 21–25</td><td>Предусматривают особый запрет монополий в системах культивации: запрет монополизации методов культивации, запрет монополизации ресурсов культивации и запрет монополизации сетей наставников</td></tr><tr><td>Статьи 26–30</td><td>Предусматривают антимонопольный орган, процедуру расследования, юридическую ответственность, систему снисхождения и дополнительные положения</td></tr></tbody></table><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Индекс правовых положений является картой правовой системы Симбиотической Цивилизации Якоря. От Симбиотической Конституции как основного закона, через трудовой закон и закон о защите прав потребителей, регулирующие благосостояние народа, и далее к пяти сопутствующим законам — всё вместе образует полную правовую систему «с Конституцией как командующим, базовыми законами как хребтом и сопутствующими законами как опорой». Эта система обеспечивает, чтобы вся деятельность симбиотической цивилизации осуществлялась в рамках верховенства права, предоставляя прочную институциональную гарантию совместного продвижения Десяти Тысяч Рас.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Симбиотическая Конституция: Общие Принципы)</li><li>41-共生劳动法 (Симбиотический Трудовой Закон)</li><li>48-司法体系与裁决机制 (Судебная система и механизм вынесения решений)</li></ul>',28)])])}const u=d(h,[["render",i]]);export{_ as __pageData,u as default};
